<?php
declare(strict_types=1);
final class Order
{
 private PDO $db;
 public function __construct(){ $this->db=Database::getInstance()->getConnection(); }
 public function find(int $id, int $userId=0):?array{$q='SELECT * FROM orders WHERE id=?';$p=[$id];if($userId>0){$q.=' AND user_id=?';$p[]=$userId;}$q.=' LIMIT 1';$s=$this->db->prepare($q);$s->execute($p);return $s->fetch()?:null;}
 public function items(int $orderId,int $userId=0):array{$q='SELECT oi.*,p.name FROM order_items oi JOIN orders o ON o.id=oi.order_id LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?';$p=[$orderId];if($userId>0){$q.=' AND o.user_id=?';$p[]=$userId;}$s=$this->db->prepare($q);$s->execute($p);return $s->fetchAll();}
 public function createFromCart(int $userId,string $address):int{$this->db->beginTransaction();try{$s=$this->db->prepare('SELECT c.id FROM carts c WHERE c.user_id=? FOR UPDATE');$s->execute([$userId]);$cid=$s->fetchColumn();if(!$cid)throw new RuntimeException('Cart is empty.');$s=$this->db->prepare('SELECT ci.product_id,ci.quantity,p.retail_price FROM cart_items ci JOIN products p ON p.id=ci.product_id WHERE ci.cart_id=? AND p.status="active"');$s->execute([$cid]);$items=$s->fetchAll();if(!$items)throw new RuntimeException('Cart is empty.');$total=0;foreach($items as $i)$total+=(float)$i['retail_price']*(int)$i['quantity'];$s=$this->db->prepare('INSERT INTO orders(user_id,status,total_amount,shipping_address) VALUES(?,"pending",?,?)');$s->execute([$userId,$total,trim($address)]);$id=(int)$this->db->lastInsertId();$s=$this->db->prepare('INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)');foreach($items as $i)$s->execute([$id,$i['product_id'],$i['quantity'],$i['retail_price']]);$this->db->prepare('DELETE FROM cart_items WHERE cart_id=?')->execute([$cid]);$this->db->commit();return $id;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
 public function updateStatus(int $orderId,string $status,int $actorId=0):bool{$allowed=['pending','processing','confirmed','shipped','delivered','completed','cancelled','failed'];if(!in_array($status,$allowed,true))throw new InvalidArgumentException('Invalid order status.');$q='UPDATE orders SET status=?';$p=[$status];if($actorId>0){$q.=' WHERE id=? AND (user_id=? OR supplier_id IN (SELECT id FROM suppliers WHERE user_id=?))';$p[]=$orderId;$p[]=$actorId;$p[]=$actorId;}else{$q.=' WHERE id=?';$p[]=$orderId;}$s=$this->db->prepare($q);$s->execute($p);return $s->rowCount()>0;}
}